 if(!selected||point((*selected)->task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&task=(**selected).task;auto&v=h.regs;if(task.child()!=C::None){uint8_t part=0;if(task.child()==C::Control){auto ptr=uint32_t(v[0].er);if(ptr<0x174ae||ptr>=0x174ae + 20*256||(ptr-0x174ae)%20)throw std::runtime_error("Invalid modulation part binding");part=uint8_t((ptr-0x174ae)/20);}task.resumeChild(part);}auto stage=task.stage();auto before=h.cycles;Boundary f(h,pc,point(task).length);const auto control=0x174aeu+unsigned(task.part())*20;auto store=[&]{unsigned at=control+task.field();return (at&1)&&h.lastwrite==int(at-1)?0u:3u;};auto cost=task.nextClocks(store);if(task.advanceBefore(cost,[&](R what)->uint32_t{return what==R::Input?uint8_t(v[5].rl):uint8_t(h.read8(control+17));},[&](bool word,uint16_t value){if(word)f.store16(control+4,int16_t(value));else f.store8(control+task.field(),int8_t(value));},store)!=cost)throw std::runtime_error("Native part modulation admission mismatch");auto dispatch=[&](unsigned target){f.call(target);h.pc=h.makepc(f.next);if(h.cycles-before!=cost)throw std::runtime_error("Native modulation dispatch clocks differ");};switch(stage){case S::DispatchControl:dispatch(0xa66a);return true;case S::CaptureInput:f.move(v[1].rl,task.input());break;case S::ClearHigh:v[1].rh=h.sub8(v[1].rh,v[1].rh);break;case S::CompareSentinel:h.sub8(v[1].rl,255);break;case S::SetSentinel:f.move(v[1].r,256);break;case S::ScaleCutoff:case S::ScaleSquare:f.shift(v[1].r,1,true);break;case S::SquareInput:v[1].r=int16_t(task.word());h.clockI(12);break;case S::ReadGate:f.move(v[1].rl,task.gate());break;case S::DispatchRefresh:dispatch(task.kind()==K::Cutoff?0x95f4:0x958e);return true;case S::DispatchGlobals:dispatch(0x7a9c);return true;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;if(h.cycles-before!=cost)throw std::runtime_error("Native modulation return clocks differ");return true;default:break;}
